internal sealed class SearchHit {public int Page,Start,Count;public RectangleF[] Boxes;}
internal sealed class TextGlyph {public int Index;public string Text;public RectangleF Bounds;}
internal sealed partial class PdfEngine {
 public string[] PageLabels(){var labels=new string[Count];for(int i=0;i<Count;i++){uint n=Native.FPDF_GetPageLabel(document,i,IntPtr.Zero,0);if(n>2&&n<4096){IntPtr p=Marshal.AllocHGlobal((int)n);try{Native.FPDF_GetPageLabel(document,i,p,n);labels[i]=Marshal.PtrToStringUni(p);}finally{Marshal.FreeHGlobal(p);}}if(string.IsNullOrEmpty(labels[i]))labels[i]=(i+1).ToString();}return labels;}
 RectangleF NormalRect(IntPtr page,double l,double t,double r,double b){PointF a=ToDisplay(page,l,t),z=ToDisplay(page,r,b);return RectangleF.FromLTRB(Math.Min(a.X,z.X),Math.Min(a.Y,z.Y),Math.Max(a.X,z.X),Math.Max(a.Y,z.Y));}
 RectangleF[] TextRects(IntPtr page,IntPtr text,int start,int count){var boxes=new List<RectangleF>();int n=Native.FPDFText_CountRects(text,start,count);for(int i=0;i<n;i++){double l,t,r,b;if(Native.FPDFText_GetRect(text,i,out l,out t,out r,out b)!=0)boxes.Add(NormalRect(page,l,t,r,b));}return boxes.ToArray();}
 public List<SearchHit> SearchPage(int index,string query,bool matchCase,Func<bool> cancel=null){var hits=new List<SearchHit>();IntPtr page=Page(index),text=Native.FPDFText_LoadPage(page);if(text==IntPtr.Zero)return hits;try{IntPtr search=Native.FPDFText_FindStart(text,query,matchCase?1u:0u,0);if(search==IntPtr.Zero)return hits;try{while(hits.Count<5000&&Native.FPDFText_FindNext(search)!=0){if(cancel!=null&&cancel())break;int start=Native.FPDFText_GetSchResultIndex(search),count=Native.FPDFText_GetSchCount(search);hits.Add(new SearchHit{Page=index,Start=start,Count=count,Boxes=TextRects(page,text,start,count)});}}finally{Native.FPDFText_FindClose(search);}}finally{Native.FPDFText_ClosePage(text);}return hits;}
 public List<TextGlyph> Glyphs(int index){IntPtr page=Page(index),text=Native.FPDFText_LoadPage(page);var glyphs=new List<TextGlyph>();if(text==IntPtr.Zero)return glyphs;try{int count=Math.Min(500000,Native.FPDFText_CountChars(text));for(int i=0;i<count;i++){uint ch=Native.FPDFText_GetUnicode(text,i);if(ch==0||ch>0x10ffff||(ch>=0xd800&&ch<=0xdfff))continue;double l,r,b,t;var glyph=new TextGlyph{Index=i,Text=char.ConvertFromUtf32((int)ch)};if(ch>32&&Native.FPDFText_GetCharBox(text,i,out l,out r,out b,out t)!=0)glyph.Bounds=NormalRect(page,l,t,r,b);glyphs.Add(glyph);}}finally{Native.FPDFText_ClosePage(text);}return glyphs;}
 public void HighlightText(int index,int start,int count,Color color){
  // Capture coordinates before expanding groups: generated whitespace can change character indices.
  IntPtr text=Native.FPDFText_LoadPage(Page(index));if(text==IntPtr.Zero)throw new InvalidOperationException("No selectable text on this page.");var quads=new List<Native.Quad>();
  try{int n=Native.FPDFText_CountRects(text,start,count);for(int i=0;i<n;i++){double l,t,r,b;if(Native.FPDFText_GetRect(text,i,out l,out t,out r,out b)!=0)quads.Add(new Native.Quad{X1=(float)l,Y1=(float)t,X2=(float)r,Y2=(float)t,X3=(float)l,Y3=(float)b,X4=(float)r,Y4=(float)b});}}finally{Native.FPDFText_ClosePage(text);}
  if(quads.Count==0)throw new InvalidOperationException("Drag across selectable text to highlight it.");EnsureEditableGroups();IntPtr page=Page(index),annot=IntPtr.Zero;int annotationIndex=-1;
  try{annot=Native.FPDFPage_CreateAnnot(page,9);Check(annot!=IntPtr.Zero,"Could not create highlight.");Check(Native.FPDFAnnot_SetColor(annot,0,color.R,color.G,color.B,100)!=0,"Could not set highlight colour.");foreach(var item in quads){var q=item;Check(Native.FPDFAnnot_AppendAttachmentPoints(annot,ref q)!=0,"Could not attach highlight to text.");}Native.FPDFAnnot_SetFlags(annot,4);annotationIndex=Native.FPDFPage_GetAnnotIndex(page,annot);}catch{if(annot!=IntPtr.Zero){int bad=Native.FPDFPage_GetAnnotIndex(page,annot);Native.FPDFPage_CloseAnnot(annot);annot=IntPtr.Zero;if(bad>=0)Native.FPDFPage_RemoveAnnot(page,bad);}throw;}finally{if(annot!=IntPtr.Zero)Native.FPDFPage_CloseAnnot(annot);}int id=annotationIndex;Commit(index,delegate{SetHighlightVisible(index,id,false);},delegate{SetHighlightVisible(index,id,true);});
 }

 void SetHighlightVisible(int page,int id,bool shown){IntPtr annot=Native.FPDFPage_GetAnnot(Page(page),id);Check(annot!=IntPtr.Zero,"Highlight is no longer available.");try{Native.FPDFAnnot_SetFlags(annot,shown?4:34);}finally{Native.FPDFPage_CloseAnnot(annot);}}
 public EditState HistoryState(){return new EditState{CanUndo=undo.Count>0,CanRedo=redo.Count>0};}
}
