internal sealed partial class MainForm {
 string[] pageLabels;readonly ToolStrip searchBar=new ToolStrip();readonly ToolStripTextBox searchInput=new ToolStripTextBox();readonly ToolStripLabel searchCount=new ToolStripLabel();readonly ToolStripButton matchCase=new ToolStripButton("Aa");ToolStripButton markButton;readonly List<SearchHit> searchHits=new List<SearchHit>();int activeHit=-1;volatile int searchEpoch;readonly Timer searchDelay=new Timer{Interval=350};
 string PageLabel(int index){return pageLabels!=null&&index>=0&&index<pageLabels.Length?pageLabels[index]:(index+1).ToString();}
 void JumpToLabel(){string value=pageBox.Text.Trim();int n=-1;if(value.StartsWith("#")){int.TryParse(value.Substring(1),out n);n--;}else if(pageLabels!=null)n=Array.FindIndex(pageLabels,p=>string.Equals(p,value,StringComparison.OrdinalIgnoreCase));if(n<0){int physical;if(int.TryParse(value,out physical))n=physical-1;}if(sizes!=null&&n>=0&&n<sizes.Length)Navigate(n);else pageBox.Text=PageLabel(pageIndex);}
 void InstallSearchToolbar(){var search=new ToolStripButton("Search"){ToolTipText="Search PDF (Ctrl+F)"};search.Click+=delegate{ShowSearch();};bar.Items.Add(new ToolStripSeparator());bar.Items.Add(search);documentTools.Add(search);markButton=new ToolStripButton("Highlight"){ToolTipText="Highlight text · drag across text, outside the editor",CheckOnClick=false};markButton.Click+=delegate{ToggleMark();};using(var b=new Bitmap(16,16))using(var g=Graphics.FromImage(b)){g.FillRectangle(Brushes.Gold,1,10,13,5);g.DrawLine(Pens.White,3,9,12,2);markButton.Image=(Bitmap)b.Clone();}bar.Items.Add(markButton);documentTools.Add(markButton);searchBar.Visible=false;searchBar.Dock=DockStyle.Top;searchBar.GripStyle=ToolStripGripStyle.Hidden;searchBar.AutoSize=false;searchBar.Height=28;searchBar.BackColor=Color.Black;searchBar.ForeColor=Color.Gainsboro;searchBar.Renderer=new DarkRenderer();searchInput.AutoSize=false;searchInput.Width=210;searchInput.BackColor=Color.FromArgb(25,29,33);searchInput.ForeColor=Color.White;searchInput.BorderStyle=BorderStyle.FixedSingle;searchBar.Items.Add(new ToolStripLabel("Find"));searchBar.Items.Add(searchInput);var prev=new ToolStripButton("◀"){ToolTipText="Previous result (Shift+F3)"};var next=new ToolStripButton("▶"){ToolTipText="Next result (F3)"};prev.Click+=delegate{NextSearch(-1);};next.Click+=delegate{NextSearch(1);};searchBar.Items.Add(prev);searchBar.Items.Add(next);matchCase.CheckOnClick=true;matchCase.ToolTipText="Match case";matchCase.CheckedChanged+=delegate{StartSearch();};searchBar.Items.Add(matchCase);searchBar.Items.Add(searchCount);var close=new ToolStripButton("×");close.Click+=delegate{HideSearch();};searchBar.Items.Add(close);searchInput.TextChanged+=delegate{searchDelay.Stop();searchDelay.Start();};searchInput.KeyDown+=delegate(object s,KeyEventArgs e){if(e.KeyCode==Keys.Enter){searchDelay.Stop();if(searchHits.Count>0)NextSearch(e.Shift?-1:1);else StartSearch();e.SuppressKeyPress=true;}if(e.KeyCode==Keys.Escape){HideSearch();e.SuppressKeyPress=true;}};searchDelay.Tick+=delegate{searchDelay.Stop();StartSearch();};canvas.MarkRequested+=delegate(int start,int count){if(editBusy)return;int index=pageIndex;ApplyEdit(delegate(PdfEngine e){e.HighlightText(index,start,count,Color.Yellow);return -1;});};FormClosed+=delegate{searchEpoch++;searchDelay.Dispose();};}
 internal void ShowSearch(){if(sizes==null||!FinishInline())return;searchBar.Visible=true;searchInput.Focus();searchInput.SelectAll();}
 void HideSearch(){searchBar.Visible=false;searchEpoch++;searchHits.Clear();activeHit=-1;canvas.SearchBoxes=new RectangleF[0];canvas.ActiveSearchBoxes=new RectangleF[0];canvas.Invalidate();canvas.Focus();}
 void StartSearch(){if(sizes==null)return;int epoch=++searchEpoch,token=generation;string query=searchInput.Text;bool exact=matchCase.Checked;searchHits.Clear();activeHit=-1;UpdateSearchOverlay();if(string.IsNullOrWhiteSpace(query)){searchCount.Text="";return;}searchCount.Text="Searching…";SearchNextPage(0,query,exact,epoch,token);}
 void SearchNextPage(int index,string query,bool exact,int epoch,int token){worker.Command(delegate(PdfEngine e){if(epoch!=searchEpoch||token!=generation)return;try{var found=e.SearchPage(index,query,exact,delegate{return epoch!=searchEpoch||token!=generation;});Post(delegate{if(epoch!=searchEpoch||token!=generation)return;searchHits.AddRange(found.Take(Math.Max(0,5000-searchHits.Count)));if(activeHit<0&&searchHits.Count>0){activeHit=0;ShowSearchHit();}else UpdateSearchOverlay();bool more=index+1<sizes.Length&&searchHits.Count<5000;searchCount.Text=searchHits.Count==0?(more?"Searching…":"No results"):(activeHit+1)+" / "+searchHits.Count+(more?" · searching…":searchHits.Count==5000?"+":"");if(more)SearchNextPage(index+1,query,exact,epoch,token);},null);}catch(Exception ex){string message=ex.Message;Post(delegate{if(epoch==searchEpoch)searchCount.Text="Search failed: "+message;},null);}});}
 void NextSearch(int delta){if(searchHits.Count==0){StartSearch();return;}activeHit=(activeHit+delta+searchHits.Count)%searchHits.Count;ShowSearchHit();searchCount.Text=(activeHit+1)+" / "+searchHits.Count;}
 static RectangleF ViewBox(RectangleF b,int turn){switch(turn%4){case 1:return new RectangleF(1-b.Bottom,b.Left,b.Height,b.Width);case 2:return new RectangleF(1-b.Right,1-b.Bottom,b.Width,b.Height);case 3:return new RectangleF(b.Top,1-b.Right,b.Height,b.Width);default:return b;}}
 void ShowSearchHit(){if(activeHit<0||activeHit>=searchHits.Count)return;var hit=searchHits[activeHit];if(pageIndex!=hit.Page)Navigate(hit.Page);UpdateSearchOverlay();if(hit.Boxes.Length>0)canvas.RevealBox(ViewBox(hit.Boxes[0],rotations[pageIndex]));}
 void UpdateSearchOverlay(){int turn=rotations==null?0:rotations[pageIndex];canvas.SearchBoxes=searchHits.Where(h=>h.Page==pageIndex).SelectMany(h=>h.Boxes).Select(b=>ViewBox(b,turn)).ToArray();canvas.ActiveSearchBoxes=activeHit>=0&&activeHit<searchHits.Count&&searchHits[activeHit].Page==pageIndex?searchHits[activeHit].Boxes.Select(b=>ViewBox(b,turn)).ToArray():new RectangleF[0];canvas.Invalidate();}
 void ToggleMark(){if(sizes==null||editBusy||!FinishInline())return;if(canvas.Editing)ToggleEditing();if(twoPages)SetTwoPages(false);canvas.MarkMode=!canvas.MarkMode;markButton.Checked=canvas.MarkMode;canvas.Cursor=canvas.MarkMode?Cursors.IBeam:Cursors.Hand;if(canvas.MarkMode){LoadMarkGlyphs();status.Text="Highlight · drag from the first character to the last · Ctrl+Z undoes";}else{canvas.MarkGlyphs.Clear();canvas.Invalidate();}}
 void LoadMarkGlyphs(){LoadViewerGlyphs(canvas,pageIndex);if(twoPages)LoadViewerGlyphs(secondCanvas,pageIndex+1);}

}
internal sealed partial class PageCanvas {
 public bool MarkMode;public List<TextGlyph> MarkGlyphs=new List<TextGlyph>();public RectangleF[] SearchBoxes=new RectangleF[0],ActiveSearchBoxes=new RectangleF[0];public event Action<int,int> MarkRequested;bool marking;int markStart=-1,markEnd=-1;
 int CharAt(Point point){PointF p=Normalized(point);TextGlyph best=null;double distance=double.MaxValue;foreach(var g in MarkGlyphs){var b=g.Bounds;if(b.IsEmpty)continue;double dx=Math.Max(0,Math.Max(b.Left-p.X,p.X-b.Right)),dy=Math.Max(0,Math.Max(b.Top-p.Y,p.Y-b.Bottom));double d=dx*dx*PageRectangle.Width*PageRectangle.Width+dy*dy*PageRectangle.Height*PageRectangle.Height;if(d<distance){distance=d;best=g;}}return best!=null&&distance<100?best.Index:-1;}
 bool MarkDown(MouseEventArgs e){if(Editing||e.Button!=MouseButtons.Left||(ModifierKeys&Keys.Alt)!=0)return false;markStart=markEnd=CharAt(e.Location);marking=markStart>=0;Capture=marking;Invalidate();return marking||MarkMode;}
 bool MarkMove(MouseEventArgs e){if(Editing||(ModifierKeys&Keys.Alt)!=0)return false;if(marking){int i=CharAt(e.Location);if(i>=0)markEnd=i;Invalidate();Cursor=Cursors.IBeam;return true;}if(!dragging)Cursor=CharAt(e.Location)>=0?Cursors.IBeam:Cursors.Hand;return MarkMode;}
 bool MarkUp(MouseEventArgs e){if(Editing||!marking)return false;marking=false;Capture=false;if(MarkMode){if(markStart>=0&&markEnd>=0&&MarkRequested!=null)MarkRequested(Math.Min(markStart,markEnd),Math.Abs(markEnd-markStart)+1);markStart=markEnd=-1;}Invalidate();return true;}

 void PaintTextOverlays(Graphics g){var state=g.Save();g.SetClip(PageRectangle);using(var fill=new SolidBrush(Color.FromArgb(85,255,220,20)))foreach(var r in SearchBoxes)g.FillRectangle(fill,ScreenRect(r));using(var fill=new SolidBrush(Color.FromArgb(110,255,130,20)))foreach(var r in ActiveSearchBoxes){Rectangle box=ScreenRect(r);g.FillRectangle(fill,box);g.DrawRectangle(Pens.OrangeRed,box);}if(marking||(!MarkMode&&markStart>=0&&markEnd>=0))using(var fill=new SolidBrush(Color.FromArgb(90,80,160,240)))foreach(var c in MarkGlyphs.Where(c=>c.Index>=Math.Min(markStart,markEnd)&&c.Index<=Math.Max(markStart,markEnd)))g.FillRectangle(fill,ScreenRect(c.Bounds));g.Restore(state);}
 public void RevealBox(RectangleF box){Rectangle r=ScreenRect(box);if(ClientRectangle.Contains(r))return;panX+=Width/2-(r.Left+r.Right)/2;panY+=Height/2-(r.Top+r.Bottom)/2;Clamp();Changed();}
}
